def pokemon_card_search(query, filters=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0405000" if __import__("os").path.isdir("./environment_mix/0405000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    # ---- helpers ----
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _norm(s):
        s = "" if s is None else str(s)
        s = s.strip().lower()
        s = re.sub(r"\s+", " ", s)
        return s

    def _b64u_enc(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64u_dec(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _gen_id(prefix):
        # deterministic-enough offline id; vendor stores "ptcg_qry_..." already
        ms = int(time.time() * 1000)
        rand = os.urandom(6).hex()
        return f"{prefix}_{ms:x}{rand}"

    def _find_usable_client():
        clients = _load("api_clients.json")
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                return c
        return None

    def _enforce_limits(client_row, log_status_on_limit=True):
        """
        Sliding 60s and UTC-day limits based on search_queries + price_lookups.
        Returns (ok:bool, error_obj_or_none, error_code_or_none).
        """
        if not client_row:
            return (True, None, None)
        if client_row.get("status") != "active":
            # Client exists but cannot be used; for ambient auth, try other client elsewhere.
            return (False, _err("UNAUTHORIZED", "No active client available for this request."), "UNAUTHORIZED")

        rpm = client_row.get("requests_per_minute_limit")
        rpd = client_row.get("requests_per_day_limit")
        if not isinstance(rpm, int) or not isinstance(rpd, int):
            return (False, _err("VALIDATION_ERROR", "Client rate limit configuration invalid."), "VALIDATION_ERROR")

        client_id = client_row.get("id")
        # count requests in last 60 seconds and today (UTC) across both audit logs
        qry = _load("search_queries.json")
        lkp = _load("price_lookups.json")
        window_start = now_dt - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day, tzinfo=datetime.timezone.utc)

        per_min = 0
        per_day = 0

        def _count(rows):
            nonlocal per_min, per_day
            for r in rows:
                if not isinstance(r, dict):
                    continue
                if r.get("client_id") != client_id:
                    continue
                ts = _parse_dt(r.get("created_at"))
                if not ts:
                    continue
                if ts >= day_start:
                    per_day += 1
                if ts >= window_start:
                    per_min += 1

        _count(qry)
        _count(lkp)

        if per_min >= rpm:
            return (False, _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=rpm, window_seconds=60), "rate_limit_per_minute_exceeded")
        if per_day >= rpd:
            return (False, _err("QUOTA_EXCEEDED", "Per-day request limit exceeded.", limit=rpd, window="UTC-day"), "rate_limit_per_day_exceeded")
        return (True, None, None)

    def _log_search(client_id, query_text, derived_filters, result_count, status, error_code, latency_ms):
        rows = _load("search_queries.json")
        row = {
            "id": _gen_id("ptcg_qry"),
            "client_id": client_id,
            "query_text": query_text,
            "filters": derived_filters,
            "result_count": int(result_count) if isinstance(result_count, int) and result_count >= 0 else 0,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, int) and latency_ms >= 0 else 0,
            "status": status,
            "error_code": error_code,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        rows.append(row)
        _save("search_queries.json", rows)
        return row

    # ---- validate inputs ----
    if not isinstance(query, str) or _norm(query) == "":
        # must still log
        client = _find_usable_client()
        latency_ms = int((time.time() - t0) * 1000)
        _log_search(client.get("id") if client else None, query if isinstance(query, str) else None, filters if isinstance(filters, dict) else None, 0, "failed", "validation_error", latency_ms)
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")

    if filters is not None and not isinstance(filters, dict):
        client = _find_usable_client()
        latency_ms = int((time.time() - t0) * 1000)
        _log_search(client.get("id") if client else None, query, None, 0, "failed", "validation_error", latency_ms)
        return _err("VALIDATION_ERROR", "filters must be an object when provided.")

    allowed_filter_keys = {"set_code", "set_name", "supertype", "rarity", "artist", "status", "collector_number", "external_id", "tcgplayer_product_id", "cardmarket_product_id", "name"}
    derived_filters = None
    if isinstance(filters, dict):
        for k in filters.keys():
            if k not in allowed_filter_keys:
                client = _find_usable_client()
                latency_ms = int((time.time() - t0) * 1000)
                _log_search(client.get("id") if client else None, query, None, 0, "failed", "validation_error", latency_ms)
                return _err("VALIDATION_ERROR", f"Unsupported filter key: {k}.", key=k)
        derived_filters = filters

    if sort is None:
        sort = "relevance"
    if not isinstance(sort, str) or sort not in ("relevance", "name", "set_name", "set_code", "collector_number", "updated_at"):
        client = _find_usable_client()
        latency_ms = int((time.time() - t0) * 1000)
        _log_search(client.get("id") if client else None, query, derived_filters, 0, "failed", "validation_error", latency_ms)
        return _err("VALIDATION_ERROR", "Invalid sort.", allowed=["relevance", "name", "set_name", "set_code", "collector_number", "updated_at"])

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 100:
        client = _find_usable_client()
        latency_ms = int((time.time() - t0) * 1000)
        _log_search(client.get("id") if client else None, query, derived_filters, 0, "failed", "validation_error", latency_ms)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

    start_offset = 0
    if cursor is not None:
        payload = _b64u_dec(cursor)
        if not isinstance(payload, dict) or "offset" not in payload:
            client = _find_usable_client()
            latency_ms = int((time.time() - t0) * 1000)
            _log_search(client.get("id") if client else None, query, derived_filters, 0, "failed", "validation_error", latency_ms)
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        off = payload.get("offset")
        if not isinstance(off, int) or off < 0:
            client = _find_usable_client()
            latency_ms = int((time.time() - t0) * 1000)
            _log_search(client.get("id") if client else None, query, derived_filters, 0, "failed", "validation_error", latency_ms)
            return _err("VALIDATION_ERROR", "Invalid cursor offset.")
        start_offset = off

    # ---- auth context + rate limiting (ambient) ----
    client = _find_usable_client()
    if client is None:
        # No active client exists; treat as unauthenticated (no rate limiting)
        client_id = None
    else:
        client_id = client.get("id")
        ok, err_obj, err_code = _enforce_limits(client)
        if not ok:
            latency_ms = int((time.time() - t0) * 1000)
            # must log rate_limited
            _log_search(client_id, query, derived_filters, 0, "rate_limited", err_code, latency_ms)
            return err_obj

    # ---- execute search ----
    cards = _load("cards.json")
    q = _norm(query)

    def _matches_card(card):
        if not isinstance(card, dict):
            return False
        if card.get("status") == "blocked":
            return False

        hay = " ".join([
            _norm(card.get("name")),
            _norm(card.get("set_name")),
            _norm(card.get("set_code")),
            _norm(card.get("collector_number")),
            _norm(card.get("rarity")),
            _norm(card.get("artist")),
            _norm(card.get("external_id")),
        ])
        # simple AND over tokens
        tokens = [t for t in re.split(r"[^\w]+", q) if t]
        for t in tokens:
            if t not in hay:
                return False

        if isinstance(filters, dict):
            for k, v in filters.items():
                if v is None:
                    continue
                if k == "supertype":
                    if not isinstance(v, str) or card.get("supertype") != v:
                        return False
                elif k == "status":
                    if not isinstance(v, str) or card.get("status") != v:
                        return False
                else:
                    # string contains match for most
                    if not isinstance(v, str):
                        return False
                    cv = card.get(k)
                    if cv is None:
                        return False
                    if _norm(v) not in _norm(cv):
                        return False
        return True

    matched = [c for c in cards if _matches_card(c)]

    # relevance scoring: count token hits in name and set_name
    tokens = [t for t in re.split(r"[^\w]+", q) if t]

    def _score(card):
        name = _norm(card.get("name"))
        setn = _norm(card.get("set_name"))
        sc = 0
        for t in tokens:
            if t in name:
                sc += 3
            if t in setn:
                sc += 1
        return sc

    def _dt_key(v):
        dt = _parse_dt(v)
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    if sort == "relevance":
        matched.sort(key=lambda c: (_score(c), _norm(c.get("name")), _norm(c.get("set_code")), _norm(c.get("collector_number"))), reverse=True)
    elif sort == "name":
        matched.sort(key=lambda c: (_norm(c.get("name")), _norm(c.get("set_name")), _norm(c.get("collector_number"))))
    elif sort == "set_name":
        matched.sort(key=lambda c: (_norm(c.get("set_name")), _norm(c.get("name")), _norm(c.get("collector_number"))))
    elif sort == "set_code":
        matched.sort(key=lambda c: (_norm(c.get("set_code")), _norm(c.get("collector_number")), _norm(c.get("name"))))
    elif sort == "collector_number":
        matched.sort(key=lambda c: (_norm(c.get("collector_number")), _norm(c.get("set_code")), _norm(c.get("name"))))
    elif sort == "updated_at":
        matched.sort(key=lambda c: (_dt_key(c.get("updated_at")), _norm(c.get("name"))), reverse=True)

    total = len(matched)
    page = matched[start_offset:start_offset + limit]
    next_off = start_offset + len(page)
    has_more = next_off < total
    next_cursor = _b64u_enc({"offset": next_off}) if has_more else None

    latency_ms = int((time.time() - t0) * 1000)
    _log_search(client_id, query, derived_filters, len(page), "succeeded", None, latency_ms)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
        },
    }

def pokemon_card_price(card_id=None, lookup_key=None, source_preference=None, currency=None, at=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0405000" if __import__("os").path.isdir("./environment_mix/0405000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        ts = ms & ((1 << 48) - 1)
        import random
        rand = random.getrandbits(80)
        val = (ts << 80) | rand
        out = []
        for _ in range(26):
            out.append(_CROCK[val & 31])
            val >>= 5
        return "".join(reversed(out))

    def _mk_id(prefix):
        return f"{prefix}{_ulid()}"

    # auth context (ambient)
    clients = _load("api_clients.json")
    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
    client = active_clients[0] if active_clients else None
    client_id = client.get("id") if client else None

    price_logs = _load("price_lookups.json")
    now = datetime.datetime.now(datetime.timezone.utc)

    def _rate_limited():
        if not client:
            return False, None
        rpm = client.get("requests_per_minute_limit")
        rpd = client.get("requests_per_day_limit")
        if not isinstance(rpm, int) or not isinstance(rpd, int):
            return False, None
        window_start = now - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
        cnt_min = 0
        cnt_day = 0
        for r in price_logs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            t = _parse_dt(r.get("created_at"))
            if not t:
                continue
            if t >= window_start:
                cnt_min += 1
            if t >= day_start:
                cnt_day += 1
        if cnt_min >= rpm:
            return True, "RATE_LIMIT"
        if cnt_day >= rpd:
            return True, "QUOTA_EXCEEDED"
        return False, None

    start = time.perf_counter()

    # validate
    if card_id is None and lookup_key is None:
        latency = int((time.perf_counter() - start) * 1000)
        log_row = {
            "id": _mk_id("ptcg_pl_"),
            "client_id": client_id,
            "card_id": None,
            "price_snapshot_id": None,
            "lookup_key": None,
            "source_preference": source_preference if isinstance(source_preference, str) else None,
            "status": "failed",
            "latency_ms": max(0, latency),
            "error_code": "VALIDATION_ERROR",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        price_logs.append(log_row)
        _save("price_lookups.json", price_logs)
        return _err("VALIDATION_ERROR", "either card_id or lookup_key must be provided")

    if card_id is not None:
        if not isinstance(card_id, str):
            return _err("VALIDATION_ERROR", "card_id must be a string")
        if not re.match(r"^ptcg_card_[0-9A-HJKMNP-TV-Z]{10,}$", card_id):
            return _err("VALIDATION_ERROR", "card_id has invalid format")

    if lookup_key is not None and not isinstance(lookup_key, str):
        return _err("VALIDATION_ERROR", "lookup_key must be a string")

    if source_preference is not None and source_preference not in {"tcgplayer", "cardmarket", "manual", "other"}:
        return _err("VALIDATION_ERROR", "invalid source_preference")

    allowed_currencies = {"USD", "EUR", "GBP", "JPY", "CAD", "AUD"}
    if currency is not None:
        if not isinstance(currency, str) or currency.upper() not in allowed_currencies:
            return _err("VALIDATION_ERROR", "invalid currency")
        currency = currency.upper()

    at_dt = None
    if at is not None:
        if not isinstance(at, str):
            return _err("VALIDATION_ERROR", "at must be a date-time string")
        at_dt = _parse_dt(at)
        if not at_dt:
            return _err("VALIDATION_ERROR", "at must be an ISO 8601 date-time")
        if at_dt.tzinfo is None:
            at_dt = at_dt.replace(tzinfo=datetime.timezone.utc)

    # rate limit check
    limited, limited_code = _rate_limited()
    if limited:
        latency = int((time.perf_counter() - start) * 1000)
        log_row = {
            "id": _mk_id("ptcg_pl_"),
            "client_id": client_id,
            "card_id": None,
            "price_snapshot_id": None,
            "lookup_key": lookup_key if isinstance(lookup_key, str) else (card_id if isinstance(card_id, str) else None),
            "source_preference": source_preference,
            "status": "rate_limited",
            "latency_ms": max(0, latency),
            "error_code": limited_code,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        price_logs.append(log_row)
        _save("price_lookups.json", price_logs)
        return _err(limited_code, "rate limit exceeded")

    cards = _load("cards.json")
    snapshots = _load("price_snapshots.json")

    # resolve card
    resolved_card = None
    if card_id is not None:
        for c in cards:
            if isinstance(c, dict) and c.get("id") == card_id:
                resolved_card = c
                break
    else:
        lk = (lookup_key or "").strip().lower()
        # try match external_id exact, then set_code+collector_number (e.g. "swsh9:154" or "swsh9 154"), then name contains
        m = re.match(r"^\s*([a-z0-9_-]+)\s*[:\s#]+(\S+)\s*$", lk)
        set_code = None
        num = None
        if m:
            set_code = m.group(1)
            num = m.group(2)
        for c in cards:
            if not isinstance(c, dict):
                continue
            if c.get("status") == "blocked":
                continue
            ext = c.get("external_id")
            if isinstance(ext, str) and ext.strip().lower() == lk and lk:
                resolved_card = c
                break
        if resolved_card is None and set_code and num:
            for c in cards:
                if not isinstance(c, dict):
                    continue
                if c.get("status") == "blocked":
                    continue
                if isinstance(c.get("set_code"), str) and isinstance(c.get("collector_number"), str):
                    if c["set_code"].lower() == set_code.lower() and c["collector_number"].lower() == num.lower():
                        resolved_card = c
                        break
        if resolved_card is None and lk:
            for c in cards:
                if not isinstance(c, dict):
                    continue
                if c.get("status") == "blocked":
                    continue
                nm = c.get("name")
                if isinstance(nm, str) and lk in nm.lower():
                    resolved_card = c
                    break

    # blocked cards are not eligible; treated as not_found but logged
    if resolved_card is None or resolved_card.get("status") == "blocked":
        latency = int((time.perf_counter() - start) * 1000)
        log_row = {
            "id": _mk_id("ptcg_pl_"),
            "client_id": client_id,
            "card_id": None if (resolved_card is None or resolved_card.get("status") == "blocked") else resolved_card.get("id"),
            "price_snapshot_id": None,
            "lookup_key": lookup_key if lookup_key is not None else card_id,
            "source_preference": source_preference,
            "status": "not_found",
            "latency_ms": max(0, latency),
            "error_code": None,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        price_logs.append(log_row)
        _save("price_lookups.json", price_logs)
        return {
            "data": None,
            "meta": {
                "status": "not_found",
                "card_id": None,
                "price_snapshot_id": None,
            },
        }

    rid = resolved_card.get("id")

    # compute "current at time of response": for each (card_id, source), current must be latest snapshot_at and status=current
    # pick among sources by preference & currency & at
    source_order = ["tcgplayer", "cardmarket", "manual", "other"]
    if source_preference in source_order:
        source_order = [source_preference] + [s for s in source_order if s != source_preference]

    # index snapshots for this card by source
    by_source = {}
    for s in snapshots:
        if not isinstance(s, dict):
            continue
        if s.get("card_id") != rid:
            continue
        src = s.get("source")
        if src not in {"tcgplayer", "cardmarket", "manual", "other"}:
            continue
        by_source.setdefault(src, []).append(s)

    def _dt(s):
        d = _parse_dt(s)
        if d and d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return d

    # determine current per source
    current_per_source = {}
    for src, rows in by_source.items():
        # latest snapshot_at among all rows for that src
        rows2 = [(r, _dt(r.get("snapshot_at"))) for r in rows]
        rows2 = [(r, d) for (r, d) in rows2 if d is not None]
        if not rows2:
            continue
        max_dt = max(d for (_, d) in rows2)
        # must have status=current AND snapshot_at == max_dt
        for (r, d) in rows2:
            if d == max_dt and r.get("status") == "current":
                current_per_source[src] = r
                break

    # selection at point-in-time: choose latest snapshot_at <= at_dt for preferred sources, but must be "current" by rule?
    # Tool spec: "point-in-time at"; however business rule constrains succeeded must reference status=current at time of response.
    # So: if at is provided, we still return the current snapshot whose snapshot_at <= at if available, else not_found.
    def _select_current():
        candidates = []
        for src in source_order:
            r = current_per_source.get(src)
            if not r:
                continue
            if currency and isinstance(r.get("currency"), str) and r.get("currency") != currency:
                continue
            d = _dt(r.get("snapshot_at"))
            if not d:
                continue
            if at_dt and d > at_dt:
                continue
            candidates.append(r)
        if candidates:
            # already in source preference order; return first
            return candidates[0]
        # if no currency match, relax currency but keep other constraints
        if currency:
            for src in source_order:
                r = current_per_source.get(src)
                if not r:
                    continue
                d = _dt(r.get("snapshot_at"))
                if not d:
                    continue
                if at_dt and d > at_dt:
                    continue
                return r
        return None

    chosen = _select_current()

    if chosen is None:
        latency = int((time.perf_counter() - start) * 1000)
        log_row = {
            "id": _mk_id("ptcg_pl_"),
            "client_id": client_id,
            "card_id": rid,
            "price_snapshot_id": None,
            "lookup_key": lookup_key if lookup_key is not None else card_id,
            "source_preference": source_preference,
            "status": "not_found",
            "latency_ms": max(0, latency),
            "error_code": None,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
