        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        ts = ms & ((1 << 48) - 1)
        import random
        rand = random.getrandbits(80)
        val = (ts << 80) | rand
        out = []
        for _ in range(26):
            out.append(_CROCK[val & 31])
            val >>= 5
        return "".join(reversed(out))

    def _mk_id(prefix):
        return f"{prefix}{_ulid()}"

    # ambient client + rate limiting (counts should apply to reads too; use search_queries as request log for get? spec doesn't.
    # Service schema has no generic request log; get is not specified to log. We'll log as a search_queries entry with query_text empty? Not allowed: tools expose none; but here tool has param. Instead, no required audit rule for get.
    # However requirement says "If schema has usage/audit/request-log collection ... EVERY call must record itself there".
