            "status": "failed",
            "error_code": "NOT_FOUND",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        })
        _save("search_queries.json", logs)
        return _err("NOT_FOUND", "card not found")

    logs.append({
