        "status": "succeeded",
        "error_code": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    })
    _save("search_queries.json", logs)

    return {"data": found}

def pokemon_price_snapshot_list(card_id, source=None, currency=None, status=None, limit=None, cursor=None, order=None, **_extra):
