    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        ts = ms & ((1 << 48) - 1)
        import random
        rand = random.getrandbits(80)
        val = (ts << 80) | rand
        out = []
        for _ in range(26):
            out.append(_CROCK[val & 31])
            val >>= 5
        return "".join(reversed(out))

    def _mk_id(prefix):
        return f"{prefix}{_ulid()}"

    def _decode_cursor(c):
        if not c:
            return None
        if not isinstance(c, str):
            return "bad"
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            return obj
        except Exception:
            return "bad"

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # ambient client + rate limiting; log call into price_lookups (audit collection exists and suitable)
    clients = _load("api_clients.json")
    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
