            t = _parse_dt(r.get("created_at"))
            if not t:
                continue
            if t >= window_start:
                cnt_min += 1
            if t >= day_start:
                cnt_day += 1
        if cnt_min >= rpm:
            return True, "RATE_LIMIT"
        if cnt_day >= rpd:
            return True, "QUOTA_EXCEEDED"
        return False, None

    start = time.perf_counter()

    if not isinstance(card_id, str) or not re.match(r"^ptcg_card_[0-9A-HJKMNP-TV-Z]{10,}$", card_id):
        return _err("VALIDATION_ERROR", "card_id has invalid format")

    if source is not None and source not in {"tcgplayer", "cardmarket", "manual", "other"}:
        return _err("VALIDATION_ERROR", "invalid source")

    allowed_currencies = {"USD", "EUR", "GBP", "JPY", "CAD", "AUD"}
    if currency is not None:
        if not isinstance(currency, str) or currency.upper() not in allowed_currencies:
            return _err("VALIDATION_ERROR", "invalid currency")
        currency = currency.upper()

    if status is not None and status not in {"current", "superseded", "invalid"}:
        return _err("VALIDATION_ERROR", "invalid status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if order is None:
        order = "snapshot_at_desc"
    if order not in {"snapshot_at_desc", "snapshot_at_asc"}:
        return _err("VALIDATION_ERROR", "invalid order")

