    if cobj == "bad":
        return _err("VALIDATION_ERROR", "invalid cursor")

    limited, limited_code = _rate_limited()
    if limited:
        latency = int((time.perf_counter() - start) * 1000)
        price_logs.append({
            "id": _mk_id("ptcg_pl_"),
