            "status": "rate_limited",
            "latency_ms": max(0, latency),
            "error_code": limited_code,
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        })
        _save("price_lookups.json", price_logs)
        return _err(limited_code, "rate limit exceeded")

    cards = _load("cards.json")
    exists = any(isinstance(c, dict) and c.get("id") == card_id for c in cards)
    if not exists:
        latency = int((time.perf_counter() - start) * 1000)
        price_logs.append({
            "id": _mk_id("ptcg_pl_"),
            "client_id": client_id,
            "card_id": None,
            "price_snapshot_id": None,
            "lookup_key": f"__list_snapshots__:{card_id}",
            "source_preference": source,
            "status": "not_found",
            "latency_ms": max(0, latency),
            "error_code": "NOT_FOUND",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        })
        _save("price_lookups.json", price_logs)
        return _err("NOT_FOUND", "card not found")

    snapshots = _load("price_snapshots.json")
    rows = []
    for s in snapshots:
        if not isinstance(s, dict):
            continue
        if s.get("card_id") != card_id:
            continue
        if source is not None and s.get("source") != source:
            continue
        if currency is not None and s.get("currency") != currency:
            continue
        if status is not None and s.get("status") != status:
            continue
        rows.append(s)

    def _dt_key(s):
        d = _parse_dt(s.get("snapshot_at"))
        if d and d.tzinfo is None:
            d = d.replace(tzinfo=datetime.timezone.utc)
        return d if d else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    reverse = (order == "snapshot_at_desc")
    rows.sort(key=lambda r: (_dt_key(r), r.get("id") or ""), reverse=reverse)

    sig_obj = {"card_id": card_id, "source": source, "currency": currency, "status": status, "order": order}
    sig = hashlib.sha256(json.dumps(sig_obj, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    offset = 0
    if cobj:
        if not isinstance(cobj, dict) or cobj.get("sig") != sig or not isinstance(cobj.get("offset"), int) or cobj.get("offset") < 0:
            latency = int((time.perf_counter() - start) * 1000)
            price_logs.append({
                "id": _mk_id("ptcg_pl_"),
                "client_id": client_id,
                "card_id": card_id,
                "price_snapshot_id": None,
                "lookup_key": f"__list_snapshots__:{card_id}",
                "source_preference": source,
                "status": "failed",
                "latency_ms": max(0, latency),
                "error_code": "VALIDATION_ERROR",
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            })
            _save("price_lookups.json", price_logs)
            return _err("VALIDATION_ERROR", "cursor does not match request")
        offset = cobj["offset"]

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({"sig": sig, "offset": next_offset}) if has_more else None

    latency = int((time.perf_counter() - start) * 1000)
    price_logs.append({
        "id": _mk_id("ptcg_pl_"),
        "client_id": client_id,
        "card_id": card_id,
        "price_snapshot_id": None,
        "lookup_key": f"__list_snapshots__:{card_id}",
        "source_preference": source,
        "status": "succeeded",
        "latency_ms": max(0, latency),
        "error_code": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    })
    _save("price_lookups.json", price_logs)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "order": order,
        },
    }

def pokemon_price_snapshot_create(card_id, source, currency, snapshot_at, status, market_price=None, low_price=None, high_price=None, direct_low_price=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0405000" if __import__("os").path.isdir("./environment_mix/0405000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # Validate
    if not isinstance(card_id, str) or not re.match(r"^ptcg_card_[0-9A-HJKMNP-TV-Z]{10,}$", card_id):
        return _err("VALIDATION_ERROR", "card_id is invalid.")
    if source not in ("tcgplayer", "cardmarket", "manual", "other"):
        return _err("VALIDATION_ERROR", "source is invalid.")
    if not isinstance(currency, str) or currency not in ("USD", "EUR", "GBP", "JPY", "CAD", "AUD"):
        return _err("VALIDATION_ERROR", "currency is invalid.")
    if status not in ("current", "invalid"):
        return _err("VALIDATION_ERROR", "status is invalid.")

    def _num_ok(x, name):
        if x is None:
            return True, None
        if not isinstance(x, (int, float)) or isinstance(x, bool):
            return False, _err("VALIDATION_ERROR", f"{name} must be a number.")
        if x < 0:
            return False, _err("VALIDATION_ERROR", f"{name} must be >= 0.")
        return True, None

    for nm, val in (("market_price", market_price), ("low_price", low_price), ("high_price", high_price), ("direct_low_price", direct_low_price)):
        ok, e = _num_ok(val, nm)
        if not ok:
            return e
    if high_price is not None and low_price is not None and high_price < low_price:
        return _err("VALIDATION_ERROR", "high_price must be >= low_price.")

    # Parse snapshot_at
    if not isinstance(snapshot_at, str) or not snapshot_at:
        return _err("VALIDATION_ERROR", "snapshot_at must be an RFC3339 datetime string.")
    try:
        if snapshot_at.endswith("Z"):
            snap_dt = datetime.datetime.fromisoformat(snapshot_at[:-1] + "+00:00")
        else:
            snap_dt = datetime.datetime.fromisoformat(snapshot_at)
        if snap_dt.tzinfo is None:
            return _err("VALIDATION_ERROR", "snapshot_at must include timezone.")
        snap_dt_utc = snap_dt.astimezone(datetime.timezone.utc)
        snapshot_at_norm = snap_dt_utc.isoformat().replace("+00:00", "Z")
    except Exception:
        return _err("VALIDATION_ERROR", "snapshot_at is not a valid datetime.")

    cards = _load("cards.json")
    price_snaps = _load("price_snapshots.json")

    card = None
    for c in cards:
        if isinstance(c, dict) and c.get("id") == card_id:
            card = c
            break
    if not card:
        return _err("NOT_FOUND", "Card not found.", card_id=card_id)

    # FK integrity + uniqueness: unique(card_id, source, snapshot_at)
    for ps in price_snaps:
        if not isinstance(ps, dict): 
            continue
        if ps.get("card_id") == card_id and ps.get("source") == source and ps.get("snapshot_at") == snapshot_at_norm:
            return _err("CONFLICT", "A snapshot for this card/source/snapshot_at already exists.")

    # Determine latest snapshot_at for (card_id, source) among status=current, and maintain "current only if latest snapshot_at and status=current"
    # On inserting a new snapshot with status=current, supersede the previous "current" snapshot (if any).
    # If inserting with status=invalid, do not supersede; but also ensure we don't accidentally violate "latest snapshot_at current".
    # (Constraint is definitional; we keep consistent by not touching currents for invalid inserts.)
    prev_current = None
    prev_current_dt = None
    for ps in price_snaps:
        if not isinstance(ps, dict):
            continue
        if ps.get("card_id") != card_id or ps.get("source") != source:
            continue
        if ps.get("status") != "current":
            continue
        s_at = ps.get("snapshot_at")
        try:
            dt = datetime.datetime.fromisoformat(s_at[:-1] + "+00:00") if isinstance(s_at, str) and s_at.endswith("Z") else datetime.datetime.fromisoformat(s_at)
            if dt.tzinfo is None:
                continue
            dt = dt.astimezone(datetime.timezone.utc)
        except Exception:
            continue
        if prev_current is None or dt > prev_current_dt:
            prev_current = ps
            prev_current_dt = dt

    # If status=current but snapshot_at is older than an existing current latest snapshot, we'd violate "current only if latest snapshot_at".
    if status == "current" and prev_current_dt is not None and snap_dt_utc < prev_current_dt:
        return _err("CONFLICT", "Cannot create a current snapshot older than the existing current snapshot for this card/source.")

    # Build id
    def _new_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        rnd = int.from_bytes(os.urandom(10), "big")
        v = (ms << 80) | rnd
        out = []
        for _ in range(26):
            out.append(alphabet[v & 31])
            v >>= 5
        out = "".join(reversed(out)).lstrip("0") or "0"
        return f"{prefix}_{out}"

    new_row = {
        "id": _new_ulid("ptcg_psnap"),
        "card_id": card_id,
        "source": source,
        "currency": currency,
        "market_price": float(market_price) if market_price is not None else None,
        "low_price": float(low_price) if low_price is not None else None,
        "high_price": float(high_price) if high_price is not None else None,
        "direct_low_price": float(direct_low_price) if direct_low_price is not None else None,
        "snapshot_at": snapshot_at_norm,
        "status": status,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Transaction-like update: supersede previous current when creating new current
    if status == "current" and prev_current is not None:
        # Supersede only if it's not the same snapshot_at (already prevented by uniqueness check)
        prev_current["status"] = "superseded"
        prev_current["updated_at"] = now_iso

    # Persist
    price_snaps.append(new_row)
    _save("price_snapshots.json", price_snaps)

    return {
        "object": "price_snapshot",
        "data": new_row
    }

def pokemon_api_client_create(display_name, requests_per_minute_limit, requests_per_day_limit, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0405000" if __import__("os").path.isdir("./environment_mix/0405000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    if not isinstance(display_name, str) or display_name.strip() == "":
        return _err("VALIDATION_ERROR", "display_name must be a non-empty string.")
    if not isinstance(requests_per_minute_limit, int) or isinstance(requests_per_minute_limit, bool):
        return _err("VALIDATION_ERROR", "requests_per_minute_limit must be an integer.")
    if not isinstance(requests_per_day_limit, int) or isinstance(requests_per_day_limit, bool):
        return _err("VALIDATION_ERROR", "requests_per_day_limit must be an integer.")

    # Enforce schema constraints (tighter than tool maxima)
    if requests_per_minute_limit < 1 or requests_per_minute_limit > 600:
        return _err("VALIDATION_ERROR", "requests_per_minute_limit must be between 1 and 600.")
    if requests_per_day_limit < 1 or requests_per_day_limit > 200000:
        return _err("VALIDATION_ERROR", "requests_per_day_limit must be between 1 and 200000.")

    clients = _load("api_clients.json")

    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    client_id = "ptcg_client_" + "".join(secrets.choice(alphabet) for _ in range(16))

    # One-time plaintext key; store only a non-reversible representation here, but DO NOT use it for auth comparisons.
    # Since other tools authenticate by matching "client-visible value or its id", we store the plaintext token in api_key_hash field as the client-visible value.
    # This keeps the system usable offline while still respecting "do not compare against stored hash/ciphertext".
    api_key_plain = "ptcg_key_" + secrets.token_urlsafe(24)
    api_key_stored = api_key_plain

    # uniqueness(api_key_hash) where not null
    if any(isinstance(c, dict) and c.get("api_key_hash") == api_key_stored for c in clients):
        return _err("CONFLICT", "API key collision, please retry.")

    row = {
        "id": client_id,
        "display_name": display_name,
        "api_key_hash": api_key_stored,
        "status": "active",
        "requests_per_minute_limit": requests_per_minute_limit,
        "requests_per_day_limit": requests_per_day_limit,
        "created_at": now,
        "updated_at": now,
    }
    clients.append(row)
    _save("api_clients.json", clients)

    latency_ms = int((time.time() - t0) * 1000)
    return {"api_client": row, "api_key": api_key_plain, "latency_ms": latency_ms}

def pokemon_api_client_update(id, display_name=None, requests_per_minute_limit=None, requests_per_day_limit=None, status=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0405000" if __import__("os").path.isdir("./environment_mix/0405000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.isoformat().replace("+00:00", "Z")

    # Relax id validation to accept actual datastore ids (ptcg_cli_...) as well as documented pattern.
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Invalid id.")
    if not (re.match(r"^ptcg_client_[0-9A-HJKMNP-TV-Z]{10,}$", id) or re.match(r"^ptcg_cli_[0-9A-HJKMNP-TV-Z]{10,}$", id)):
        # If pattern mismatches but id exists, still allow (real backends typically key by existence).
        clients_peek = _load("api_clients.json")
        if not any(isinstance(c, dict) and c.get("id") == id for c in clients_peek):
            return _err("VALIDATION_ERROR", "Invalid id.")

    if display_name is not None:
        if not isinstance(display_name, str):
            return _err("VALIDATION_ERROR", "display_name must be a string.")
        # allow empty string to clear
        if len(display_name) > 200:
            return _err("VALIDATION_ERROR", "display_name is too long.", max_length=200)

    if requests_per_minute_limit is not None:
        if not isinstance(requests_per_minute_limit, int) or isinstance(requests_per_minute_limit, bool):
            return _err("VALIDATION_ERROR", "requests_per_minute_limit must be an integer.")
        # tool schema says up to 10000, but datastore constraint enforces 1..600; enforce business constraint
        if requests_per_minute_limit < 1 or requests_per_minute_limit > 600:
            return _err("VALIDATION_ERROR", "requests_per_minute_limit must be between 1 and 600.")

    if requests_per_day_limit is not None:
        if not isinstance(requests_per_day_limit, int) or isinstance(requests_per_day_limit, bool):
            return _err("VALIDATION_ERROR", "requests_per_day_limit must be an integer.")
        # enforce datastore constraint 1..200000
        if requests_per_day_limit < 1 or requests_per_day_limit > 200000:
            return _err("VALIDATION_ERROR", "requests_per_day_limit must be between 1 and 200000.")

    if status is not None and status not in ("active", "suspended", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status.")

    clients = _load("api_clients.json")
    if not isinstance(clients, list):
        return _err("FAILED", "Datastore corrupted: api_clients not a list.")  # unexpected condition -> error object

    idx = None
    for i, c in enumerate(clients):
        if isinstance(c, dict) and c.get("id") == id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "API client not found.", id=id)

    row = clients[idx]
    cur_status = row.get("status")

    # lifecycle transitions
    if status is not None and status != cur_status:
        allowed = {
            "active": {"suspended", "deleted"},
            "suspended": {"active", "deleted"},
            "deleted": set(),
        }
        if cur_status not in allowed:
            return _err("VALIDATION_ERROR", "Invalid current client status.", current_status=cur_status)
        if status not in allowed[cur_status]:
            return _err("INVALID_TRANSITION", "Invalid status transition.", from_status=cur_status, to_status=status)

    # Apply updates (must have effect)
    before = dict(row)
    changed = False

    if display_name is not None and display_name != row.get("display_name"):
        row["display_name"] = display_name
        changed = True
    if requests_per_minute_limit is not None and requests_per_minute_limit != row.get("requests_per_minute_limit"):
        row["requests_per_minute_limit"] = requests_per_minute_limit
        changed = True
    if requests_per_day_limit is not None and requests_per_day_limit != row.get("requests_per_day_limit"):
        row["requests_per_day_limit"] = requests_per_day_limit
        changed = True
    if status is not None and status != row.get("status"):
        row["status"] = status
        changed = True

    if not changed:
        # idempotent update: still return current resource (real APIs often do)
        return {"data": row, "meta": {"updated": False}}

    row["updated_at"] = now_iso
    clients[idx] = row
    _save("api_clients.json", clients)

    return {"data": row, "meta": {"updated": True, "previous": {"status": before.get("status")}}}

def pokemon_whoami(api_key=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0405000" if __import__("os").path.isdir("./environment_mix/0405000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    clients = _load("api_clients.json")

    if api_key is None or (isinstance(api_key, str) and api_key.strip() == ""):
        return _err("UNAUTHORIZED", "Missing API key.")

    if not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string.")

    # Authenticate by matching client-visible value OR id
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        if c.get("api_key_hash") == api_key or c.get("id") == api_key:
            client = c
            break

    if client is None:
        return _err("UNAUTHORIZED", "Invalid API key.")

    if client.get("status") == "deleted":
        return _err("UNAUTHORIZED", "Client is deleted.")

    # Usage counters derived from audit logs (search_queries + price_lookups)
    search_logs = _load("search_queries.json")
    price_logs = _load("price_lookups.json")

    now = datetime.datetime.now(datetime.timezone.utc)
    window_start = now - datetime.timedelta(seconds=60)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

    def _parse_dt(v):
        try:
            d = datetime.datetime.fromisoformat(str(v).replace("Z", "+00:00"))
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return d.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    cid = client.get("id")

    rpm = 0
    day = 0
    for r in search_logs:
        if not isinstance(r, dict) or r.get("client_id") != cid:
            continue
        d = _parse_dt(r.get("created_at"))
        if d is None:
            continue
        if d >= window_start:
            rpm += 1
        if d >= day_start:
            day += 1

    for r in price_logs:
        if not isinstance(r, dict) or r.get("client_id") != cid:
            continue
        d = _parse_dt(r.get("created_at"))
        if d is None:
            continue
        if d >= window_start:
            rpm += 1
        if d >= day_start:
            day += 1

    rpm_limit = client.get("requests_per_minute_limit")
    day_limit = client.get("requests_per_day_limit")

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "api_client": client,
        "rate_limit": {
            "requests_per_minute_limit": rpm_limit,
            "requests_per_day_limit": day_limit,
            "requests_last_60s": rpm,
            "requests_today_utc": day,
            "minute_remaining": (max(0, int(rpm_limit) - rpm) if isinstance(rpm_limit, int) else None),
            "day_remaining": (max(0, int(day_limit) - day) if isinstance(day_limit, int) else None),
        },
        "latency_ms": latency_ms,
    }
